{
  "schemaVersion": "0.2",
  "slug": "kbd",
  "name": "Kbd",
  "status": "experimental",
  "purpose": "Represents a keyboard key or shortcut.",
  "scenarios": [
    "Show a keyboard shortcut",
    "Label a key in documentation",
    "Indicate a modifier key"
  ],
  "props": {
    "children": {
      "type": "node",
      "required": true,
      "description": "Key label."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Key rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "text",
      "tooltip",
      "page"
    ],
    "allowedChildren": [
      "text"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for interactive buttons.",
    "Do not wrap entire paragraphs in kbd."
  ],
  "a11y": {
    "role": "generic",
    "keyboard": [],
    "focus": "Not focusable.",
    "labeling": "Contents provide the key name.",
    "wcag": [
      "1.3.1"
    ]
  },
  "responsive": {
    "strategy": "Inline display.",
    "breakpoints": {
      "compact": "Inline.",
      "medium": "Inline.",
      "large": "Inline."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "No mirroring required for individual key symbols.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "kbd",
    "states": [
      "default"
    ],
    "intents": [
      "show-shortcut"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface KbdProps {
  children: ReactNode
  className?: string
}

export function Kbd({ children, className }: KbdProps) {
  const classes = ['cu-kbd', className].filter(Boolean).join(' ')
  return <kbd className={classes} data-ai-role="kbd" data-ai-state="default" data-ai-intent="show-shortcut">{children}</kbd>
}

.cu-kbd {
  display: inline-block;
  padding-block: calc(var(--cu-space-1) / 2);
  padding-inline: var(--cu-space-1);
  border: 1px solid var(--cu-color-border-default);
  border-radius: var(--cu-radius-sm);
  background: var(--cu-color-background-default);
  color: var(--cu-color-fg-default);
  font-family: monospace;
  font-size: 0.875em;
}
